import { ThemeEditor, type ThemeDraft } from "march/components/theme-editor"

// tek renkten tema: sıfırdan başla, yalnız Renkler sekmesi; başlık taslağın ana rengiyle boyanır
export function OneColorTheme() {
  let $draft: ThemeDraft | null = null
  return <div sx={{ flex: "col", gap: 2 }}>
    <span sx={{ text: ["2xl", "bold"] }} style={{ color: $draft?.light.primary ?? "inherit" }}>Bir renk seç, tema hazır</span>
    <ThemeEditor bind:value={$draft} base="scratch" tabs={["colors"]} presets={false} applyButton={false} storageKey={false} share={false} warnUnsaved={false} />
  </div>
}

import { Toolbar, Button } from "march/ui"
import { ThemeEditor, presetCopy, type ThemeDraft } from "march/components/theme-editor"

// ThemeEditor'ün bütün özellikleri: value + setValue + onChange, başlangıç (base), sekmeler, önizleme ve anahtarları,
// kayıt anahtarı, paylaşım bağlantısı, ayrılırken uyarı, onSave, salt okunur, hazır temalar satırı, ad alanı,
// geri al / yinele, "uygulamaya uygula", kendi metinler ve sınıf. Üstteki anahtarlar bazılarını canlı açıp kapatır.
export function ThemeEditorLab() {
  let $draft: ThemeDraft | null = presetCopy("neon")
  let $changes = 0
  let $saved = "yok"
  let $readonly = false
  let $preview = false
  return <div sx={{ flex: "col", gap: 2 }}>
    <Toolbar label="Lab ayarları">
      <Button size="sm" variant="secondary" pressed={$readonly} on:click={() => $readonly = !$readonly}>Salt okunur</Button>
      <Button size="sm" variant="secondary" pressed={$preview} on:click={() => $preview = !$preview}>Önizleme</Button>
      <span sx={{ text: "sm" }}>Değişiklik: {$changes} · Kaydedilen: {$saved}</span>
    </Toolbar>
    {() => <ThemeEditor
      value={$draft}
      setValue={(d) => $draft = d}
      onChange={() => $changes++}
      base="neon"
      tabs={["colors", "shape", "motion", "export"]}
      preview={$preview}
      previewControls={false}
      storageKey="lab-theme"
      share={false}
      warnUnsaved={false}
      onSave={(d) => $saved = d.name}
      readonly={$readonly}
      presets={false}
      nameField
      historyButtons
      applyButton={false}
      labels={{ editor: "Lab teması", name: "Tema adı", save: "Kaydet", unsaved: "Kaydedilmedi", saved: "Kaydedildi", tabs: { colors: "Palet", shape: "Biçim", motion: "Devinim", export: "Çıktı" } }}
      class="lab-te"
    />}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { ThemeEditorLab } from "./ThemeEditorLab.tsx"

// ThemeEditorLab'in testleri: düzenleyici bir parça olarak yüklenir; önce görünmesi beklenir
const ready = async () => {
  const s = renderTest(() => <ThemeEditorLab />)
  await s.wait(() => s.get(".lab-te .m-te-name"), { timeout: 5000 })
  return s
}

test("kendi metinler: sekme adları ve düzenleyicinin adı", async () => {
  const s = await ready()
  expect(s.get(".lab-te")?.getAttribute("aria-label")).toBe("Lab teması")
  expect(s.find("Palet")).toBeTruthy()
  expect(s.find("Çıktı")).toBeTruthy()
  expect(s.find("Tipografi")).toBe(null)
})

test("ad değişince onChange sayar, Kaydet onSave'e adı verir", async () => {
  const s = await ready()
  await s.type("Tema adı", "Lab neonu")
  expect(s.sees("Değişiklik: 0")).toBe(false)
  await s.click(".m-te-save")
  expect(s.sees("Kaydedilen: Lab neonu")).toBe(true)
})

test("kapalı parçalar: hazır temalar satırı, uygula düğmesi ve önizleme yok", async () => {
  const s = await ready()
  expect(s.get(".lab-te .m-te-bases")).toBe(null)
  expect(s.get(".lab-te .m-te-apply")).toBe(null)
  expect(s.get(".lab-te .m-te-stage")).toBe(null)
})

test("salt okunur açılınca ad alanı kilitlenir", async () => {
  const s = await ready()
  const locked = () => !!s.get(".lab-te .m-te-title input")?.hasAttribute("readonly")
  expect(locked()).toBe(false)
  await s.click("Salt okunur")
  await s.wait(locked, { timeout: 5000 })
  expect(locked()).toBe(true)
})
